function validate([s]) {
  if (typeof s !== 'string' || s.length !== 5) return 's must have exactly 5 characters.';
  if (s[2] !== ':') return 'The middle character of s must be a colon.';
  if (!/^[A-Z]$/.test(s[0]) || !/^[A-Z]$/.test(s[3])) return 'Columns must be uppercase letters A to Z.';
  if (!/^[1-9]$/.test(s[1]) || !/^[1-9]$/.test(s[4])) return 'Rows must be digits 1 to 9.';
  if (s[0] > s[3]) return 'The first column must not come after the second.';
  if (s[1] > s[4]) return 'The first row must not be larger than the second.';
  return null;
}

