function cellsInRange(s) {
  const firstColumn = s.charCodeAt(0);
  const lastColumn = s.charCodeAt(3);
  const firstRow = Number(s[1]);
  const lastRow = Number(s[4]);
  const cells = [];

  for (let column = firstColumn; column <= lastColumn; column++) {
    const letter = String.fromCharCode(column);
    for (let row = firstRow; row <= lastRow; row++) {
      cells.push(letter + row);
    }
  }
  return cells;
}

