function cellsInRange(s) {
  const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const all = [];
  for (const letter of letters) for (let row = 1; row <= 9; row++) all.push(letter + row);
  const [from, to] = s.split(':');
  const inside = all.filter(cell => cell[0] >= from[0] && cell[0] <= to[0] && cell[1] >= from[1] && cell[1] <= to[1]);
  return inside.sort((a, b) => a[0] === b[0] ? Number(a[1]) - Number(b[1]) : a.charCodeAt(0) - b.charCodeAt(0));
}

