function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  let c1, c2, r1, r2;
  if (size === 'large') {
    c1 = pick(0, 4); c2 = pick(21, 25); r1 = pick(1, 2); r2 = pick(8, 9);
  } else {
    c1 = pick(0, 25); c2 = Math.min(25, c1 + pick(0, 3)); r1 = pick(1, 9); r2 = Math.min(9, r1 + pick(0, 3));
  }
  const letter = code => String.fromCharCode(65 + code);
  return [letter(c1) + r1 + ':' + letter(c2) + r2];
}
